__NUXT_JSONP__("/inclusion/eventos/presentan_informe_con_diagnostico_y_propuestas_para_dignificar_la_labor_de_las_trabajadoras_agricolas", (function(a,b,c,d,e,f){return {data:[{post:{slug:"presentan_informe_con_diagnostico_y_propuestas_para_dignificar_la_labor_de_las_trabajadoras_agricolas",title:"Presentan informe con diagnóstico y propuestas para dignificar la labor de las trabajadoras agrícolas",date:"2025-10-01T21:15:12.605Z",img:"https:\u002F\u002Fucarecdn.com\u002F880400a6-0330-4ab6-9eca-1e8727446864\u002F-\u002Fpreview\u002F",autor:"Ethos",category:"inclusion",extracto:"Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México, es un documento elaborado por UNIDAS —alianza integrada por Ethos, Oxfam México, ProDESC y Fundación Avina—, que expone el panorama de precariedad que enfrentan las jornaleras agrícolas y propone acciones para garantizarles un trabajo justo y digno.",toc:[],body:{type:"root",children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las trabajadoras agrícolas en México son clave para la seguridad alimentaria, pues cultivan los alimentos que llegan a las mesas mexicanas, e incluso a otros países; sin embargo, enfrentan circunstancias laborales marcadas por la precariedad y la violación de sus derechos laborales, de acuerdo con el informe "},{type:b,tag:e,props:{},children:[{type:b,tag:"a",props:{href:"https:\u002F\u002Funidas.mx\u002Finformes\u002F",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:f}]}]},{type:a,value:", elaborado por UNIDAS, la alianza de Ethos Innovación en Políticas Públicas, Oxfam México, ProDESC y Fundación Avina."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En la presentación de este documento, Nubia Díaz Rubio, de la Unión de Jornaleros Agrícolas, destacó que "},{type:b,tag:e,props:{},children:[{type:a,value:"Sembrando el cambio"}]},{type:a,value:" es la fotografía de lo que ellas enfrentan todos los días. El 90% de las trabajadoras no tiene contrato formal, mientras que 86% no cuenta con IMSS, y en caso de accidentes laborales, las empresas recurren a prácticas ilegales como entregar “pases” médicos. A esto, dijo, se suman la violencia de género, la poca vigilancia de las condiciones laborales así como las dobles jornadas que enfrentan."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Respecto al último tema, destacó que en la más reciente década, se redujeron las “guarderías de campo” del IMSS un 50%, pasando de 13 en 2012 a 6 para 2024, además de que hubo un recorte presupuestal del 37% para este servicio. Esto obliga a las trabajadoras a abandonar sus empleos o incluso a llevar a sus hijos e hijas a sus centros de trabajo, lo que aumenta el riesgo de accidentes, propicia el trabajo infantil y agudiza el rezago y la deserción escolar."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Mónica Corona, directora de Inclusión y Desarrollo Sostenible en Ethos, explicó que el problema central que enfrenta este sector es un sistema de barreras estructurales: la falta de contratos escritos, la carencia generalizada de seguridad social, altos riesgos en el trabajo por falta de equipo, protocolos y condiciones seguras, violencia de género y discriminación, sobrecarga de trabajo de cuidados, así como vigilancia insuficiente de derechos, como se señala en el informe."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ante este panorama, Marianela Fernández, de Oxfam, señaló que desde Unidas se proponen acciones coordinadas y contundentes entre autoridades estatales y federales: que se garantice el cumplimiento de la ley mediante una vigilancia efectiva y transparente que fortalezca la inspección con perspectiva de género; se asegure la afiliación real al IMSS de las trabajadoras y se erradiquen los mecanismos informales de acceso a la salud (“pases”); se amplíen y adapten los servicios de guardería para las familias agrícolas; y finalmente, que se implementen protocolos contra la violencia y discriminación de las mujeres trabajadoras agrícolas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En el evento también participaron Valentina Zendejas, de Fundación Avina; Valeria Berumen, de ProDESC; así como representantes de la Alianza Hortofrutícola Internacional para el Fomento de la Responsabilidad Social, A.C.; el Colegio de México; la Organización de las Naciones Unidas para la Alimentación y la Agricultura; Mujeres Unidas en Defensa de las Jornaleras e Indígenas; la Coalición de Trabajadoras y Trabajadores Migrantes de Sinaloa; la Secretaría de las Mujeres; la Secretaría del Trabajo y Previsión Social; la Universidad Nacional Autónoma de México; y la Unión de Jornaleros Agrícolas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" es el primero de cuatro documentos, centrados en el trabajo agrícola, la industria de la indumentaria, las plataformas digitales y las trabajadoras del hogar. El objetivo es visibilizar el trabajo de las mujeres y las condiciones laborales que enfrentan: falta de derechos, sobrecarga de cuidados sin infraestructura adecuada y esquemas de contratación que incumplen la normativa."}]},{type:a,value:c}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fpresentan_informe_con_diagnostico_y_propuestas_para_dignificar_la_labor_de_las_trabajadoras_agricolas",extension:".md",createdAt:"2025-11-25T01:24:03.258Z",updatedAt:"2025-11-25T01:24:03.259Z"}}],fetch:{},mutations:[]}}("text","element","\n","p","em","Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México")));